            "对乙酰氨基酚过量→N-乙酰半胱氨酸；肝素过量→鱼精蛋白；华法林过量→维生素K。",
            "地高辛中毒→停药+补钾，严重用抗地高辛抗体；阿片类中毒(呼吸抑制)→纳洛酮。"
